        function parseMapData(text) {
            if (!text || typeof text !== 'string') {
                 console.error("Map data is empty or not a string.");
                return null;
            }
            // Initialize data structure
            const data = {
                title: null,
                moveBlocked: false, // Default to false
                locations: [],
                conversingPartners: [],
                externalAreas: [],
                currentUserPosition: { x: null, y: null }, // 新增：存储用户当前位置坐标
                roads: []
            };
            let processedText = text.trim();
             console.log("Starting map data parsing. Raw text length:", processedText.length);

            // --- Extract Header Tags ---
            // Title
            const titleMatch = processedText.match(/^\[TITLE:\s*(.*?)\]\s*\n?/);
            if (titleMatch) {
                data.title = titleMatch[1].trim();
                processedText = processedText.substring(titleMatch[0].length).trimStart(); // Remove tag and leading whitespace
                 console.log("Extracted title:", data.title);
            } else {
                 console.log("No title found.");
            }

            // Conversing Partners
            const conversingMatch = processedText.match(/^\[CONVERSING:\s*(.*?)\]\s*\n?/);
            if (conversingMatch && conversingMatch[1]) {
                const partnerNames = conversingMatch[1].split(',').map(name => name.trim()).filter(name => name);
                data.conversingPartners = partnerNames;
                processedText = processedText.substring(conversingMatch[0].length).trimStart(); // Remove tag
                 console.log("Extracted conversing partners (names):", data.conversingPartners);
            } else {
                 console.log("No conversing partners found.");
            }

            // External Areas
            const externalAreasMatch = processedText.match(/^\[EXTERNAL_AREAS:\s*(.*?)\]\s*\n?/);
            if (externalAreasMatch && externalAreasMatch[1]) {
                data.externalAreas = externalAreasMatch[1].split(',').map(name => name.trim()).filter(name => name);
                processedText = processedText.substring(externalAreasMatch[0].length).trimStart(); // Remove tag
                 console.log("Extracted external areas:", data.externalAreas);
            } else {
                 console.log("No external areas found.");
            }

            // Move Block
            const moveBlockMatch = processedText.match(/^\[MOVEBLOCK:\s*(YES|NO)\]\s*\n?/i); // Case-insensitive YES/NO
            if (moveBlockMatch) {
                data.moveBlocked = moveBlockMatch[1].toUpperCase() === 'YES';
                processedText = processedText.substring(moveBlockMatch[0].length).trimStart(); // Remove tag
                 console.log("Extracted moveBlocked:", data.moveBlocked);
            } else {
                 console.log("No MOVEBLOCK tag found, defaulting to false.");
            }

            // Current Position (New Tag)
            const currentPosMatch = processedText.match(/^\[CURRENT_POS:\s*(\d+)\|(\d+)\]\s*\n?/);
            if (currentPosMatch) {
                data.currentUserPosition.x = parseInt(currentPosMatch[1], 10);
                data.currentUserPosition.y = parseInt(currentPosMatch[2], 10);
                processedText = processedText.substring(currentPosMatch[0].length).trimStart(); // Remove tag
                console.log("Extracted current user position:", data.currentUserPosition);
            } else {
                console.log("No CURRENT_POS tag found.");
            }

            // --- Process Location and Road Lines ---
