                        const wCoord = mainLocationMatch[4] ? parseInt(mainLocationMatch[4], 10) : null;
                        const hCoord = mainLocationMatch[5] ? parseInt(mainLocationMatch[5], 10) : null;
                         console.log(`  Potential main location found: "${potentialMainName}" at (${xCoord ?? 'N/A'}, ${yCoord ?? 'N/A'}) with size (${wCoord ?? 'N/A'}x${hCoord ?? 'N/A'})`);

                        // Finalize the previous main location *before* starting the new one.
                        if (currentMainLocation) {
                             console.log(`    Finalizing previous main location: "${currentMainLocation.name}" with ${currentMainLocation.subLocations.length} sub-locations.`);
                            data.locations.push(currentMainLocation);
                        }
                        // Start a new main location object
                        currentMainLocation = {
                            name: potentialMainName,
                            x: xCoord,
                            y: yCoord,
                            width: wCoord,
                            height: hCoord,
                            subLocations: []
                        };
                         console.log(`    Started new main location: "${potentialMainName}"`);

                    } else if (subLocationMatch && currentMainLocation) {
                        // --- Found a sub-location line ---
                        const subName = subLocationMatch[1].trim();
                        const charactersText = subLocationMatch[2] ? subLocationMatch[2].trim() : '';
                         console.log(`    Found sub-location: "${subName}" for main location "${currentMainLocation.name}"`);
                        const characters = [];
                        try {
                            // Character Parsing Regex (keep existing robust one)
                            const characterRegex = /([^,{}\s][^,{}]*?)\s*(?:\{((?:[^{}]|\{[^{}]*\})*)\})?\s*(?:,|$)/g;
                            let charMatch;
                             console.log(`      Parsing characters text: "${charactersText}"`);
                            characterRegex.lastIndex = 0; // Reset regex state

                            while ((charMatch = characterRegex.exec(charactersText)) !== null) {
                                let parsedName = charMatch[1] ? charMatch[1].trim() : null;
                                let parsedDescription = charMatch[2] ? charMatch[2].trim() : null;

                                 // console.log(`        Regex Match: Full='${charMatch[0]}', Name='${parsedName}', Desc='${parsedDescription}'`); // Verbose log

                                // Basic cleaning and validation
                                if (parsedName && parsedName.length > 0 && parsedName.toLowerCase() !== '无') {
                                    // Remove trailing punctuation like ']' if accidentally included
                                    parsedName = parsedName.replace(/[\])}]+$/, '').trim();
                                    if (parsedName) { // Check again after cleaning
                                        characters.push({ name: parsedName, description: parsedDescription });
                                         console.log(`        Added character: "${parsedName}" ${parsedDescription ? '(with description)' : ''}`);
                                    }
                                } else if (parsedName) {
                                     console.log(`        Skipped character: "${parsedName}"`);
                                }

                                // Prevent infinite loops on zero-length matches or empty strings
                                if (charMatch[0].length === 0) {
                                     console.warn("        Zero-length regex match detected, advancing index.");
                                     characterRegex.lastIndex++;
                                }
                                if (characterRegex.lastIndex === charMatch.index) {
                                     console.warn("        Regex lastIndex did not advance, breaking loop.");
                                     break; // Prevent potential infinite loop
                                }
                            }
                        } catch (charError) {
                             console.error(`      Error parsing characters for sublocation "${subName}":`, charError);
                        }
                        currentMainLocation.subLocations.push({ name: subName, characters: characters });
                         console.log(`    Finished sub-location "${subName}", found ${characters.length} characters.`);
                    } else if (currentMainLocation) {
                         console.log(`    Skipping line within main location "${currentMainLocation.name}" (not sub-location): "${line}"`);
                    } else {
                         console.log(`  Skipping line (not main location, sub-location, or road): "${line}"`);
                    }
                }

                // Add the last processed main location if it exists
                if (currentMainLocation) {
                     console.log(`Finalizing last main location: "${currentMainLocation.name}" with ${currentMainLocation.subLocations.length} sub-locations.`);
                    data.locations.push(currentMainLocation);
                }

                 console.log(`Finished parsing locations and roads. Total main locations: ${data.locations.length}, Total roads: ${data.roads.length}, Current Pos: (${data.currentUserPosition.x ?? 'N/A'}, ${data.currentUserPosition.y ?? 'N/A'})`);
                 console.log("Map data parsing complete. Final data structure (locations might be large):", { ...data, locations: `[${data.locations.length} main locations]`, roads: `[${data.roads.length} roads]` });
                return data;
            } catch (error) {
                 console.error("Error during map data parsing process:", error);
                return null;
            }
        }

