        function updateConversationPartnersDisplay(partnerNames = []) { // Expects array of names now
             console.log("Inside updateConversationPartnersDisplay. Received partnerNames:", partnerNames);
            const partnersSection = document.getElementById('current-conversation-partners');
            const buttonsContainer = document.getElementById('partner-buttons');
            if (!partnersSection || !buttonsContainer) {
                return;
            }
            buttonsContainer.innerHTML = '';

            // More robust check: ensure it's an array and has items.
            const shouldShow = Array.isArray(partnerNames) && partnerNames.length > 0;
             console.log(`  Should show partners section? ${shouldShow}`);

            if (shouldShow) {
                partnerNames.forEach(name => { // Iterate through names
                    if (!name || typeof name !== 'string') {
                         console.warn("    Skipping invalid partner name:", name);
                         return;
                    }
                    const button = document.createElement('button');
                    button.className = 'partner-button';
                    button.dataset.characterName = name; // Store only the name
                    // No need to store description in dataset anymore
                    button.innerHTML = `<i class="fas fa-user-check"></i> ${name}`;

                    button.addEventListener('click', () => {
                        // Find character data dynamically using the stored name
                        const partnerData = findCharacterInMapData(name, mapData.locations); // Lookup happens here!
                        const partnerDescription = partnerData ? partnerData.description : null; // Get description if found

                        // Find location info (optional, for context if needed later)
                        if (partnerData && partnerData.mainLocationName && partnerData.subLocationName) {
                            selectedMain = mapData.locations.find(loc => loc.name === partnerData.mainLocationName);
                            if (selectedMain) {
                                selectedSub = selectedMain.subLocations.find(sub => sub.name === partnerData.subLocationName);
                            } else {
                                selectedSub = null;
                            }
                        } else {
                            selectedMain = null;
                            selectedSub = null;
                        }

                        // Call selectCharacter with the dynamically found description and the trigger button
                        selectCharacter(name, partnerDescription, event.currentTarget);
                    });
                    buttonsContainer.appendChild(button);
                });
                partnersSection.classList.remove('hidden');
            } else {
                partnersSection.classList.add('hidden');
            }
        }

        function findCharacterInMapData(characterName, locations = []) {
            if (!locations) return null;
            for (const mainLoc of locations) {
                if (!mainLoc || !Array.isArray(mainLoc.subLocations)) continue;
                for (const subLoc of mainLoc.subLocations) {
                    if (!subLoc || !Array.isArray(subLoc.characters)) continue;
                    const foundChar = subLoc.characters.find(char => char && char.name === characterName);
                    if (foundChar) {
                        return { ...foundChar, mainLocationName: mainLoc.name, subLocationName: subLoc.name };
                    }
                }
            }
            return null;
        }


        function handleNewMessage(messageData) {

            if (!messageData || messageData.is_user || !mapData || !mapData.locations) {
                return;
            }

            const messageContent = messageData.mes;

            const locationMatch = messageContent.match(/在(.*?)\s*-\s*(.*?)>/);
            if (locationMatch && locationMatch[1] && locationMatch[2]) {
                const mainLocName = locationMatch[1].trim();
                const subLocName = locationMatch[2].trim();

                const targetMainLocation = mapData.locations.find(loc => loc.name === mainLocName);
                if (targetMainLocation) {
                    const targetSubLocation = targetMainLocation.subLocations.find(sub => sub.name === subLocName);
                    if (targetSubLocation) {
                        selectMainLocation(targetMainLocation);
                        requestAnimationFrame(() => {
                            if (selectedMain && selectedMain.name === mainLocName) {
                                const currentTargetSubLocation = selectedMain.subLocations.find(sub => sub.name === subLocName);
                                if (currentTargetSubLocation) {
                                    setTimeout(() => {
                                        selectSubLocation(currentTargetSubLocation);
                                    }, 50);
                                }
                            }
                        });
                        return;
                    }
                }
            }
        }


