                document.documentElement.style.setProperty('--theme-button-hover-color', settings.buttonColor); // Fallback
            }


            document.documentElement.style.setProperty('--theme-bg-dark', settings.uiBgColor);
            // Adjust medium/light backgrounds based on the dark background
             try {
                let r = parseInt(settings.uiBgColor.slice(1, 3), 16);
                let g = parseInt(settings.uiBgColor.slice(3, 5), 16);
                let b = parseInt(settings.uiBgColor.slice(5, 7), 16);
                let rMed = Math.min(255, r + 18); let gMed = Math.min(255, g + 18); let bMed = Math.min(255, b + 18);
                let rLight = Math.min(255, r + 36); let gLight = Math.min(255, g + 36); let bLight = Math.min(255, b + 36);
                const medColor = `#${rMed.toString(16).padStart(2, '0')}${gMed.toString(16).padStart(2, '0')}${bMed.toString(16).padStart(2, '0')}`;
                const lightBgColor = `#${rLight.toString(16).padStart(2, '0')}${gLight.toString(16).padStart(2, '0')}${bLight.toString(16).padStart(2, '0')}`;
                document.documentElement.style.setProperty('--theme-bg-medium', medColor);
                document.documentElement.style.setProperty('--theme-bg-light', lightBgColor);
                // Adjust border based on new background
                let rBorder = Math.min(255, r + 50); let gBorder = Math.min(255, g + 50); let bBorder = Math.min(255, b + 50);
                const borderColor = `#${rBorder.toString(16).padStart(2, '0')}${gBorder.toString(16).padStart(2, '0')}${bBorder.toString(16).padStart(2, '0')}`;
                document.documentElement.style.setProperty('--theme-border-light', borderColor);

            } catch (e) {
                console.error("Error calculating derived UI background/border colors:", e);
                 // Fallback to defaults if calculation fails
                document.documentElement.style.setProperty('--theme-bg-medium', '#3e4451');
                document.documentElement.style.setProperty('--theme-bg-light', '#505663');
                document.documentElement.style.setProperty('--theme-border-light', '#606673');
