        }

        function loadSettings() {
            try {
                const saved = localStorage.getItem('mapPluginSettings');
                if (saved) {
                    // Merge saved settings with defaults to ensure all keys exist
                    return { ...defaultSettings, ...JSON.parse(saved) };
                }
            } catch (e) {
                console.error("Failed to load settings from localStorage:", e);
            }
            return { ...defaultSettings }; // Return a copy of defaults if load fails or no settings saved
        }

        // This function now needs the element references passed to it and checks each element robustly
        function updateSettingsUI(settings, elements) {
             if (!elements) {
                 console.error("Elements object not provided to updateSettingsUI");
                 return;
             }

             // Check and assign locally before accessing properties
             const fontSelect = elements.fontStyleSelect;
             if (fontSelect) fontSelect.value = settings.fontFamily;
             else console.error("fontStyleSelect element is null in updateSettingsUI");

             const titleFontSelect = elements.titleFontStyleSelect; // Title font select
             if (titleFontSelect) titleFontSelect.value = settings.titleFontFamily;
             else console.error("titleFontStyleSelect element is null in updateSettingsUI");

             const sizeSlider = elements.fontSizeSlider;
             if (sizeSlider) sizeSlider.value = parseInt(settings.fontSize, 10);
             else console.error("fontSizeSlider element is null in updateSettingsUI");

             const sizeValue = elements.fontSizeValue;
             if (sizeValue) sizeValue.textContent = settings.fontSize;
             else console.error("fontSizeValue element is null in updateSettingsUI");

             const fontColor = elements.fontColorPicker;
             if (fontColor) fontColor.value = settings.fontColor;
             else console.error("fontColorPicker element is null in updateSettingsUI");

             const uiColor = elements.uiColorPicker;
             if (uiColor) uiColor.value = settings.uiColor;
             else console.error("uiColorPicker element is null in updateSettingsUI");

             const uiBgColor = elements.uiBgColorPicker;
             if (uiBgColor) uiBgColor.value = settings.uiBgColor;
             else console.error("uiBgColorPicker element is null in updateSettingsUI");

             const buttonColor = elements.buttonColorPicker; // Button color picker
             if (buttonColor) buttonColor.value = settings.buttonColor;
             else console.error("buttonColorPicker element is null in updateSettingsUI");

             const shadow = elements.shadowToggle;
             if (shadow) shadow.checked = settings.shadowsEnabled;
             else console.error("shadowToggle element is null in updateSettingsUI");
        }

        function setupSettingsPanel() {
            // --- Get ALL elements INSIDE this function ---
            const settingsPanel = document.getElementById('settings-panel');
            const settingsToggleBtn = document.getElementById('settings-toggle-btn');
            const settingsCloseBtn = document.getElementById('settings-close-btn');
            const fontStyleSelect = document.getElementById('font-style-select');
            const titleFontStyleSelect = document.getElementById('title-font-style-select'); // Get title font select
            const fontSizeSlider = document.getElementById('font-size-slider');
            const fontSizeValue = document.getElementById('font-size-value');
            const fontColorPicker = document.getElementById('font-color-picker');
            const uiColorPicker = document.getElementById('ui-color-picker');
            const uiBgColorPicker = document.getElementById('ui-bg-color-picker');
            const buttonColorPicker = document.getElementById('button-color-picker'); // Get button color picker
            const shadowToggle = document.getElementById('shadow-toggle');
            const applyBtn = document.getElementById('settings-apply-btn');
            const resetBtn = document.getElementById('settings-reset-btn');
            const mapInterface = document.querySelector('.map-interface');
            const presetContainer = document.getElementById('preset-schemes-container'); // Get preset container

             // --- Check each element individually after retrieval ---
             if (!settingsPanel) { console.error("Settings Panel element (#settings-panel) not found!"); return; }
             if (!settingsToggleBtn) { console.error("Settings Toggle Button element (#settings-toggle-btn) not found!"); return; }
             if (!settingsCloseBtn) { console.error("Settings Close Button element (#settings-close-btn) not found!"); return; }
             if (!fontStyleSelect) { console.error("Font Style Select element (#font-style-select) not found!"); return; }
             if (!titleFontStyleSelect) { console.error("Title Font Style Select element (#title-font-style-select) not found!"); return; } // Check title font select
             if (!fontSizeSlider) { console.error("Font Size Slider element (#font-size-slider) not found!"); return; }
             if (!fontSizeValue) { console.error("Font Size Value element (#font-size-value) not found!"); return; }
             if (!fontColorPicker) { console.error("Font Color Picker element (#font-color-picker) not found!"); return; }
             if (!uiColorPicker) { console.error("UI Color Picker element (#ui-color-picker) not found!"); return; }
             if (!uiBgColorPicker) { console.error("UI BG Color Picker element (#ui-bg-color-picker) not found!"); return; }
             if (!buttonColorPicker) { console.error("Button Color Picker element (#button-color-picker) not found!"); return; } // Check button color picker
             if (!shadowToggle) { console.error("Shadow Toggle element (#shadow-toggle) not found!"); return; }
             if (!applyBtn) { console.error("Apply Button element (#settings-apply-btn) not found!"); return; }
             if (!resetBtn) { console.error("Reset Button element (#settings-reset-btn) not found!"); return; }
             if (!mapInterface) { console.error("Map Interface element (.map-interface) not found!"); return; }
             if (!presetContainer) { console.error("Preset Schemes Container element (#preset-schemes-container) not found!"); return; } // Check preset container


              // Bundle elements for easy passing (now we know they exist)
              const settingElements = {
                  settingsPanel, settingsToggleBtn, settingsCloseBtn, fontStyleSelect,
                  titleFontStyleSelect, // Add title font select
                  fontSizeSlider, fontSizeValue, fontColorPicker, uiColorPicker,
                  uiBgColorPicker, buttonColorPicker, // Add button color picker
                  shadowToggle, applyBtn, resetBtn, mapInterface, presetContainer // Add preset container to elements
              };

             // --- Define open/close functions locally or ensure they have access ---
            function openSettingsPanelLocal() {
                settingsPanel.classList.remove('hidden');
                settingsToggleBtn.classList.add('active');
            }

            function closeSettingsPanelLocal() {
                settingsPanel.classList.add('hidden');
                settingsToggleBtn.classList.remove('active');
            }


            // --- Load, Apply, Update ---
            let currentSettings = loadSettings(); // Use let if it might be reassigned by reset
            applySettings(currentSettings, mapInterface); // Pass mapInterface
            updateSettingsUI(currentSettings, settingElements); // Pass elements

            // Get settings panel content element reference here for positioning
            const settingsPanelContent = settingsPanel.querySelector('.settings-content'); // Corrected selector
            if (!settingsPanelContent) { console.error("Settings Panel Content element (.settings-content) not found!"); return; }


            // --- Define open/close functions locally or ensure they have access ---
            function openSettingsPanelLocal() {
                console.log("DEBUG: openSettingsPanelLocal called for centering");
                settingsPanel.classList.remove('hidden'); // Show the overlay
                settingsToggleBtn.classList.add('active');

                // Get the actual panel content element to center
                const settingsPanelDialog = settingsPanel.querySelector('.settings-panel-content'); // Target the inner content box
                if (!settingsPanelDialog) {
                    console.error("Could not find .settings-panel-content to center.");
                    return;
                }

                // Use requestAnimationFrame to ensure the panel is rendered before centering
                requestAnimationFrame(() => {
                    positionModalCenter(settingsPanelDialog); // Center the content box
                });
            }

            function closeSettingsPanelLocal() {
                settingsPanel.classList.add('hidden');
                settingsToggleBtn.classList.remove('active');
            }


            // --- Add Event Listeners ---
            settingsToggleBtn.addEventListener('click', openSettingsPanelLocal);
            settingsCloseBtn.addEventListener('click', closeSettingsPanelLocal);
            settingsPanel.addEventListener('click', (event) => { // Close on overlay click
                if (event.target === settingsPanel) {
                    closeSettingsPanelLocal();
                }
            });

            fontSizeSlider.addEventListener('input', () => {
                fontSizeValue.textContent = `${fontSizeSlider.value}px`;
            });

             applyBtn.addEventListener('click', () => {
                 const newSettings = {
                     fontFamily: fontStyleSelect.value,
                     titleFontFamily: titleFontStyleSelect.value, // Get title font value
                     fontSize: `${fontSizeSlider.value}px`,
                     fontColor: fontColorPicker.value,
                     uiColor: uiColorPicker.value,
                     uiBgColor: uiBgColorPicker.value,
                     buttonColor: buttonColorPicker.value, // Get button color value
                     shadowsEnabled: shadowToggle.checked
                 };
                 applySettings(newSettings, mapInterface); // Pass mapInterface
                saveSettings(newSettings);
                closeSettingsPanelLocal(); // Close after applying
            });

            resetBtn.addEventListener('click', () => {
                currentSettings = { ...defaultSettings }; // Reset currentSettings object as well
                applySettings(currentSettings, mapInterface); // Pass mapInterface
                updateSettingsUI(currentSettings, settingElements); // Pass elements
                saveSettings(currentSettings); // Save reset settings
                // closeSettingsPanelLocal(); // Optionally close
            });

            // --- Populate Preset Schemes ---
            presetContainer.innerHTML = ''; // Clear existing presets
            presetColorSchemes.forEach(scheme => {
                const presetButton = document.createElement('button');
                presetButton.className = 'preset-scheme-button';
                presetButton.title = scheme.name;
                // Simple visual representation using background colors
                presetButton.innerHTML = `
                    <span class="preset-swatch" style="background-color: ${scheme.uiBgColor}; border-color: ${scheme.uiColor};">
                        <span class="preset-swatch-inner" style="background-color: ${scheme.buttonColor};"></span>
                        <span class="preset-swatch-text" style="color: ${scheme.fontColor};">Aa</span>
                    </span>
                    <span class="preset-name">${scheme.name}</span>
                `;
                presetButton.addEventListener('click', () => {
                    // Update currentSettings with the selected scheme's values
                    // Create a new object to avoid modifying the original preset object
                    currentSettings = {
                        ...currentSettings, // Keep existing settings like font family/size
                        fontColor: scheme.fontColor,
                        uiColor: scheme.uiColor,
                        uiBgColor: scheme.uiBgColor,
                        buttonColor: scheme.buttonColor
                        // shadowsEnabled is not part of the color scheme, keep existing value
                    };
                    // Apply the settings visually
                    applySettings(currentSettings, mapInterface);
                    // Update the UI controls (pickers, etc.) to match the preset
                    updateSettingsUI(currentSettings, settingElements);
                    // Note: We don't save here, user needs to click "Apply"
                });
                presetContainer.appendChild(presetButton);
            });
            // --- End Populate Preset Schemes ---
        }
        // --- End Settings Panel Logic ---


        function init() {
            setupEventListeners();
            // Delay setupSettingsPanel slightly to potentially allow other scripts to finish modifying DOM
            setTimeout(() => {
                try {
                    setupSettingsPanel(); // Initialize settings panel
                } catch (e) {
                    console.error("Error during delayed setupSettingsPanel execution:", e);
                }
            }, 0); // 0ms delay pushes execution to the end of the current event loop cycle
            processMapData();
        }

        document.addEventListener('DOMContentLoaded', init);
    </script>

