        function parseMapData(text) {
            if (!text || typeof text !== 'string') {
                 console.error("Map data is empty or not a string.");
                return null;
            }
            // Initialize data structure
            const data = {
                title: null,
                moveBlocked: false, // Default to false
                locations: [],
                conversingPartners: [],
                externalAreas: [],
                currentUserPosition: { x: null, y: null }, // 新增：存储用户当前位置坐标
                roads: []
            };
            let processedText = text.trim();
             console.log("Starting map data parsing. Raw text length:", processedText.length);

            // --- Extract Header Tags ---
            // Title
            const titleMatch = processedText.match(/^\[TITLE:\s*(.*?)\]\s*\n?/);
            if (titleMatch) {
                data.title = titleMatch[1].trim();
                processedText = processedText.substring(titleMatch[0].length).trimStart(); // Remove tag and leading whitespace
                 console.log("Extracted title:", data.title);
            } else {
                 console.log("No title found.");
            }

            // Conversing Partners
            const conversingMatch = processedText.match(/^\[CONVERSING:\s*(.*?)\]\s*\n?/);
            if (conversingMatch && conversingMatch[1]) {
                const partnerNames = conversingMatch[1].split(',').map(name => name.trim()).filter(name => name);
                data.conversingPartners = partnerNames;
                processedText = processedText.substring(conversingMatch[0].length).trimStart(); // Remove tag
                 console.log("Extracted conversing partners (names):", data.conversingPartners);
            } else {
                 console.log("No conversing partners found.");
            }

            // External Areas
            const externalAreasMatch = processedText.match(/^\[EXTERNAL_AREAS:\s*(.*?)\]\s*\n?/);
            if (externalAreasMatch && externalAreasMatch[1]) {
                data.externalAreas = externalAreasMatch[1].split(',').map(name => name.trim()).filter(name => name);
                processedText = processedText.substring(externalAreasMatch[0].length).trimStart(); // Remove tag
                 console.log("Extracted external areas:", data.externalAreas);
            } else {
                 console.log("No external areas found.");
            }

            // Move Block
            const moveBlockMatch = processedText.match(/^\[MOVEBLOCK:\s*(YES|NO)\]\s*\n?/i); // Case-insensitive YES/NO
            if (moveBlockMatch) {
                data.moveBlocked = moveBlockMatch[1].toUpperCase() === 'YES';
                processedText = processedText.substring(moveBlockMatch[0].length).trimStart(); // Remove tag
                 console.log("Extracted moveBlocked:", data.moveBlocked);
            } else {
                 console.log("No MOVEBLOCK tag found, defaulting to false.");
            }

            // Current Position (New Tag)
            const currentPosMatch = processedText.match(/^\[CURRENT_POS:\s*(\d+)\|(\d+)\]\s*\n?/);
            if (currentPosMatch) {
                data.currentUserPosition.x = parseInt(currentPosMatch[1], 10);
                data.currentUserPosition.y = parseInt(currentPosMatch[2], 10);
                processedText = processedText.substring(currentPosMatch[0].length).trimStart(); // Remove tag
                console.log("Extracted current user position:", data.currentUserPosition);
            } else {
                console.log("No CURRENT_POS tag found.");
            }

            // --- Process Location and Road Lines ---
            try {
                const lines = processedText.split('\n').map(line => line.trim()).filter(line => line);
                let currentMainLocation = null;
                 console.log(`Processing ${lines.length} lines of location/road data...`);

                for (const line of lines) {
                    // Refined Regex:
                    // Group 1: Main location name (cannot contain | or ])
                    // Group 2 (optional): |x|y part
                    // Group 3 (optional): x coordinate
                    // Group 4 (optional): y coordinate
                    // Group 5 (optional): |w|h part
                    // Group 6 (optional): width
                    // Group 7 (optional): height
                    const mainLocationRegex = /^\[([^|\]]+)(?:\|(\d+)\|(\d+))?(?:\|(\d+)\|(\d+))?\]$/;
                    const mainLocationMatch = line.match(mainLocationRegex);
                    const subLocationMatch = line.match(/^-\s*([^:]+?)\s*:(.*)/);
                    const roadMatch = line.match(/^\[ROAD\|([^|]+)\|(\d+)(?:\|([^\]]+))?\]$/);

                    if (roadMatch) {
                        // --- Found a road line ---
                        // Finalize previous main location before processing road
                        if (currentMainLocation) {
                             console.log(`Finalizing previous main location: "${currentMainLocation.name}" with ${currentMainLocation.subLocations.length} sub-locations.`);
                            data.locations.push(currentMainLocation);
                            currentMainLocation = null; // Reset for next location
                        }

                        const pointsStr = roadMatch[1];
                        const width = parseInt(roadMatch[2], 10);
                        const color = roadMatch[3] || '#888888';
                        const points = pointsStr.split(';').map(p => p.trim()).filter(p => p.includes(',')).map(p => {
                            const coords = p.split(',');
                            return { x: parseInt(coords[0], 10), y: parseInt(coords[1], 10) };
                        }).filter(p => !isNaN(p.x) && !isNaN(p.y));

                        if (points.length >= 2) {
                            data.roads.push({ points: points.map(p => `${p.x},${p.y}`).join(' '), width, color });
                             console.log(`  Found road: ${points.length} points, width ${width}, color ${color}`);
                        } else {
                             console.warn(`  Skipping invalid road definition: ${line}`);
                        }
                    } else if (mainLocationMatch) {
                        // --- Found a main location line ---
                        const potentialMainName = mainLocationMatch[1].trim();
                        // Check if it's a known header tag mistakenly formatted as location
                        if (['TITLE', 'CONVERSING', 'EXTERNAL_AREAS', 'MOVEBLOCK', 'ROAD'].includes(potentialMainName.toUpperCase())) {
                             console.warn(`  Skipping line resembling a header tag: "${line}"`);
                             continue; // Skip this line
                        }

                        const xCoord = mainLocationMatch[2] ? parseInt(mainLocationMatch[2], 10) : null;
                        const yCoord = mainLocationMatch[3] ? parseInt(mainLocationMatch[3], 10) : null;
                        const wCoord = mainLocationMatch[4] ? parseInt(mainLocationMatch[4], 10) : null;
                        const hCoord = mainLocationMatch[5] ? parseInt(mainLocationMatch[5], 10) : null;
                         console.log(`  Potential main location found: "${potentialMainName}" at (${xCoord ?? 'N/A'}, ${yCoord ?? 'N/A'}) with size (${wCoord ?? 'N/A'}x${hCoord ?? 'N/A'})`);

                        // Finalize the previous main location *before* starting the new one.
                        if (currentMainLocation) {
                             console.log(`    Finalizing previous main location: "${currentMainLocation.name}" with ${currentMainLocation.subLocations.length} sub-locations.`);
                            data.locations.push(currentMainLocation);
                        }
                        // Start a new main location object
                        currentMainLocation = {
                            name: potentialMainName,
                            x: xCoord,
                            y: yCoord,
                            width: wCoord,
                            height: hCoord,
                            subLocations: []
                        };
                         console.log(`    Started new main location: "${potentialMainName}"`);

                    } else if (subLocationMatch && currentMainLocation) {
                        // --- Found a sub-location line ---
                        const subName = subLocationMatch[1].trim();
                        const charactersText = subLocationMatch[2] ? subLocationMatch[2].trim() : '';
                         console.log(`    Found sub-location: "${subName}" for main location "${currentMainLocation.name}"`);
                        const characters = [];
                        try {
                            // Character Parsing Regex (keep existing robust one)
                            const characterRegex = /([^,{}\s][^,{}]*?)\s*(?:\{((?:[^{}]|\{[^{}]*\})*)\})?\s*(?:,|$)/g;
                            let charMatch;
                             console.log(`      Parsing characters text: "${charactersText}"`);
                            characterRegex.lastIndex = 0; // Reset regex state

                            while ((charMatch = characterRegex.exec(charactersText)) !== null) {
                                let parsedName = charMatch[1] ? charMatch[1].trim() : null;
                                let parsedDescription = charMatch[2] ? charMatch[2].trim() : null;

                                 // console.log(`        Regex Match: Full='${charMatch[0]}', Name='${parsedName}', Desc='${parsedDescription}'`); // Verbose log

                                // Basic cleaning and validation
                                if (parsedName && parsedName.length > 0 && parsedName.toLowerCase() !== '无') {
                                    // Remove trailing punctuation like ']' if accidentally included
                                    parsedName = parsedName.replace(/[\])}]+$/, '').trim();
                                    if (parsedName) { // Check again after cleaning
                                        characters.push({ name: parsedName, description: parsedDescription });
                                         console.log(`        Added character: "${parsedName}" ${parsedDescription ? '(with description)' : ''}`);
                                    }
                                } else if (parsedName) {
                                     console.log(`        Skipped character: "${parsedName}"`);
                                }

                                // Prevent infinite loops on zero-length matches or empty strings
                                if (charMatch[0].length === 0) {
                                     console.warn("        Zero-length regex match detected, advancing index.");
                                     characterRegex.lastIndex++;
                                }
                                if (characterRegex.lastIndex === charMatch.index) {
                                     console.warn("        Regex lastIndex did not advance, breaking loop.");
                                     break; // Prevent potential infinite loop
                                }
                            }
                        } catch (charError) {
                             console.error(`      Error parsing characters for sublocation "${subName}":`, charError);
                        }
                        currentMainLocation.subLocations.push({ name: subName, characters: characters });
                         console.log(`    Finished sub-location "${subName}", found ${characters.length} characters.`);
                    } else if (currentMainLocation) {
                         console.log(`    Skipping line within main location "${currentMainLocation.name}" (not sub-location): "${line}"`);
                    } else {
                         console.log(`  Skipping line (not main location, sub-location, or road): "${line}"`);
                    }
                }

                // Add the last processed main location if it exists
                if (currentMainLocation) {
                     console.log(`Finalizing last main location: "${currentMainLocation.name}" with ${currentMainLocation.subLocations.length} sub-locations.`);
                    data.locations.push(currentMainLocation);
                }

                 console.log(`Finished parsing locations and roads. Total main locations: ${data.locations.length}, Total roads: ${data.roads.length}, Current Pos: (${data.currentUserPosition.x ?? 'N/A'}, ${data.currentUserPosition.y ?? 'N/A'})`);
                 console.log("Map data parsing complete. Final data structure (locations might be large):", { ...data, locations: `[${data.locations.length} main locations]`, roads: `[${data.roads.length} roads]` });
                return data;
            } catch (error) {
                 console.error("Error during map data parsing process:", error);
                return null;
            }
        }

        function renderMapInterface(mapData) {
            const titleElement = document.getElementById('map-title');
            if (mapData && mapData.title) {
                titleElement.textContent = mapData.title;
            } else {
                titleElement.textContent = '通用地图导航';
            }


            if (!mapData || !mapData.locations) {
                 const mainLocationsContainer = document.getElementById('main-locations');
                 mainLocationsContainer.innerHTML = '<p class="error-message">地图数据加载失败</p>';
                 document.getElementById('sub-locations').classList.add('hidden');
                 document.getElementById('location-details').classList.add('hidden');
                 document.getElementById('movement-alert').classList.add('hidden');
                 return;
            }
            hasMoveBlock = mapData.moveBlocked;
            document.getElementById('movement-alert').classList.add('hidden'); // Keep movement alert logic

            const svgMap = document.getElementById('visual-map');
            const tooltip = document.getElementById('map-tooltip');
            const svgNS = "http://www.w3.org/2000/svg";
            svgMap.innerHTML = ''; // Clear previous SVG content

            // --- Render Roads FIRST (so they are underneath locations) ---
            if (mapData.roads && mapData.roads.length > 0) {
                mapData.roads.forEach(road => {
                    const polyline = document.createElementNS(svgNS, 'polyline');
                    polyline.setAttribute('points', road.points);
                    polyline.setAttribute('stroke', road.color);
                    polyline.setAttribute('stroke-width', road.width);
                    polyline.setAttribute('fill', 'none'); // Roads are lines, not filled shapes
                    polyline.setAttribute('stroke-linecap', 'round'); // Nicer line endings
                    polyline.setAttribute('stroke-linejoin', 'round'); // Nicer line corners
                    polyline.classList.add('map-road');
                    svgMap.appendChild(polyline);
                });
            }

            // --- Render Locations on SVG (on top of roads) ---
            const defaultWidth = 100; // Default size if width/height not provided
            const defaultHeight = 60;

            mapData.locations.forEach(location => {
                if (location && typeof location.name === 'string' && location.x !== null && location.y !== null) {
                    const locWidth = location.width || defaultWidth; // Use provided width or default
                    const locHeight = location.height || defaultHeight; // Use provided height or default
                    const labelOffsetDy = locHeight / 2 + 5; // Adjust label position based on actual height

                    const group = document.createElementNS(svgNS, 'g');
                    group.setAttribute('transform', `translate(${location.x}, ${location.y})`);
                    group.classList.add('map-location-group');
                    group.dataset.location = location.name; // Store name
                    group.style.pointerEvents = 'all'; // Force pointer events on the group

                    // Create the rectangle with actual dimensions
                    const rect = document.createElementNS(svgNS, 'rect');
                    rect.style.pointerEvents = 'all'; // Force pointer events on the rect as well
                    rect.setAttribute('width', locWidth); // Use actual width
                    rect.setAttribute('height', locHeight); // Use actual height
                    rect.setAttribute('rx', 5); // Rounded corners
                    rect.setAttribute('ry', 5);
                    rect.classList.add('map-location-rect');
                    // Add click listener to the group instead of the rectangle
                    group.addEventListener('click', (event) => {
                        // --- MORE SPECIFIC DEBUG LOG ---
                        console.log(`DEBUG: Click detected on map group for location: "${location.name}". Target element:`, event.target);
                        // --- END DEBUG LOG ---
                        selectMainLocation(location);
                    });
                    group.appendChild(rect);

                    // Create the text label, centered in the actual rectangle
                    const text = document.createElementNS(svgNS, 'text');
                    text.setAttribute('x', locWidth / 2); // Center horizontally based on actual width
                    text.setAttribute('y', labelOffsetDy); // Position vertically based on actual height
                    text.classList.add('map-location-label');
                    text.textContent = location.name;
                    group.appendChild(text);

                    // Add tooltip listeners (optional, can be enhanced later)
                    if (tooltip) {
                        group.addEventListener('mouseenter', (e) => {
                            tooltip.textContent = location.name; // Simple tooltip for now
                            tooltip.style.left = `${e.clientX + 10}px`;
                            tooltip.style.top = `${e.clientY + 10}px`;
                            tooltip.classList.add('visible');
                        });
                        group.addEventListener('mousemove', (e) => {
                            tooltip.style.left = `${e.clientX + 10}px`;
                            tooltip.style.top = `${e.clientY + 10}px`;
                        });
                        group.addEventListener('mouseleave', () => {
                            tooltip.classList.remove('visible');
                        });
                    }

                    svgMap.appendChild(group);
                } else if (location && typeof location.name === 'string') {
                    console.warn(`Location "${location.name}" is missing coordinates and won't be rendered visually.`);
                    // Optionally, render these non-coordinate locations in a separate list?
                }
            });

            // --- Current Location (Title) is now only shown in the header ---
            // Removed the code block that rendered the central currentLocation rectangle

            resetSelection(false); // Keep reset logic

            const switchAreaBtn = document.getElementById('switch-area-button');
            if (mapData.externalAreas && mapData.externalAreas.length > 0) {
                switchAreaBtn.classList.remove('hidden');
                const newSwitchAreaBtn = switchAreaBtn.cloneNode(true);
                switchAreaBtn.parentNode.replaceChild(newSwitchAreaBtn, switchAreaBtn);
                newSwitchAreaBtn.addEventListener('click', () => showExternalAreas(mapData.externalAreas));
            } else {
                switchAreaBtn.classList.add('hidden');
            }

            // Add a test listener directly to the SVG
            const svgMapElement = document.getElementById('visual-map');
            if (svgMapElement) {
                svgMapElement.addEventListener('click', (event) => {
                    console.log('SVG element clicked!', event.target);
                });
            } else {
                    console.error("Could not find SVG element to attach test listener.");
            }

            // --- Render Current User Position (Red Dot) ---
            if (mapData.currentUserPosition && typeof mapData.currentUserPosition.x === 'number' && typeof mapData.currentUserPosition.y === 'number') {
                const userDot = document.createElementNS(svgNS, 'circle');
                userDot.setAttribute('cx', mapData.currentUserPosition.x);
                userDot.setAttribute('cy', mapData.currentUserPosition.y);
                userDot.setAttribute('r', 6); // Radius of the dot
                userDot.setAttribute('fill', 'red');
                userDot.setAttribute('stroke', 'white'); // Optional white border for visibility
                userDot.setAttribute('stroke-width', 1.5);
                userDot.classList.add('current-user-position'); // Add a class for potential styling/selection
                userDot.style.pointerEvents = 'none'; // Make sure the dot doesn't interfere with clicks on locations below it
                svgMap.appendChild(userDot);
                 console.log(`Rendered user position dot at (${mapData.currentUserPosition.x}, ${mapData.currentUserPosition.y})`);
            } else {
                 console.log("User position coordinates not available or invalid, skipping dot rendering.");
            }
        }


        function selectMainLocation(location) {
            console.log("selectMainLocation called with location:", location ? location.name : 'undefined/null'); // Log function call
            if (!location || !location.subLocations) {
                console.log("selectMainLocation returning early: location or subLocations missing."); // Log early return
                return;
            }
            console.log("selectMainLocation proceeding for:", location.name); // Log proceeding

            selectedMain = location;
            selectedSub = null;
            selectedCharacterName = null;
            updateActionButtonState();

            document.getElementById('location-details').classList.add('hidden');
            document.getElementById('sub-locations').classList.add('hidden');
            document.getElementById('switch-area-button').classList.remove('selected'); // Keep this

            // Update selection state for SVG elements
            document.querySelectorAll('#visual-map .map-location-group').forEach(group => {
                // Don't select the 'current-location' visually
                if (!group.classList.contains('current-location')) {
                    group.classList.toggle('selected', group.dataset.location === location.name);
                }
            });


            const subLocationsContainer = document.getElementById('sub-locations'); // Keep sub-location logic
            subLocationsContainer.innerHTML = '';

            if (location.subLocations.length === 0) {
                 subLocationsContainer.innerHTML = '<p class="info-message">此区域下没有具体的探索地点。</p>';
                 subLocationsContainer.classList.remove('hidden');
                 return;
            }

            location.subLocations.forEach(subLocation => {
                if (!subLocation || typeof subLocation.name !== 'string') {
                    return;
                }
                const button = document.createElement('button');
                button.className = 'sub-location-button';
                // Use unified icon function for sub-locations
                const iconClass = getIconClassForLocation(subLocation.name);
                button.innerHTML = `<i class="fas ${iconClass}"></i> ${subLocation.name}`;
                button.dataset.sublocation = subLocation.name;
                button.addEventListener('click', () => selectSubLocation(subLocation));
                subLocationsContainer.appendChild(button);
            });

            subLocationsContainer.classList.remove('hidden');
        }

        function selectSubLocation(subLocation) {
            if (!subLocation || !subLocation.characters || !selectedMain) {
                return;
            }

            selectedSub = subLocation;
