                         console.warn("    Skipping invalid partner name:", name);
                         return;
                    }
                    const button = document.createElement('button');
                    button.className = 'partner-button';
                    button.dataset.characterName = name; // Store only the name
                    // No need to store description in dataset anymore
                    button.innerHTML = `<i class="fas fa-user-check"></i> ${name}`;

                    button.addEventListener('click', () => {
                        // Find character data dynamically using the stored name
                        const partnerData = findCharacterInMapData(name, mapData.locations); // Lookup happens here!
                        const partnerDescription = partnerData ? partnerData.description : null; // Get description if found

                        // Find location info (optional, for context if needed later)
                        if (partnerData && partnerData.mainLocationName && partnerData.subLocationName) {
                            selectedMain = mapData.locations.find(loc => loc.name === partnerData.mainLocationName);
