                                selectedSub = null;
                            }
                        } else {
                            selectedMain = null;
                            selectedSub = null;
                        }

                        // Call selectCharacter with the dynamically found description and the trigger button
                        selectCharacter(name, partnerDescription, event.currentTarget);
                    });
                    buttonsContainer.appendChild(button);
                });
                partnersSection.classList.remove('hidden');
            } else {
                partnersSection.classList.add('hidden');
            }
        }

        function findCharacterInMapData(characterName, locations = []) {
            if (!locations) return null;
            for (const mainLoc of locations) {
                if (!mainLoc || !Array.isArray(mainLoc.subLocations)) continue;
                for (const subLoc of mainLoc.subLocations) {
                    if (!subLoc || !Array.isArray(subLoc.characters)) continue;
                    const foundChar = subLoc.characters.find(char => char && char.name === characterName);
                    if (foundChar) {
                        return { ...foundChar, mainLocationName: mainLoc.name, subLocationName: subLoc.name };
                    }
                }
            }
            return null;
        }


        function handleNewMessage(messageData) {

            if (!messageData || messageData.is_user || !mapData || !mapData.locations) {
                return;
            }

            const messageContent = messageData.mes;

            const locationMatch = messageContent.match(/在(.*?)\s*-\s*(.*?)>/);
            if (locationMatch && locationMatch[1] && locationMatch[2]) {
                const mainLocName = locationMatch[1].trim();
                const subLocName = locationMatch[2].trim();

                const targetMainLocation = mapData.locations.find(loc => loc.name === mainLocName);
                if (targetMainLocation) {
                    const targetSubLocation = targetMainLocation.subLocations.find(sub => sub.name === subLocName);
                    if (targetSubLocation) {
                        selectMainLocation(targetMainLocation);
                        requestAnimationFrame(() => {
                            if (selectedMain && selectedMain.name === mainLocName) {
                                const currentTargetSubLocation = selectedMain.subLocations.find(sub => sub.name === subLocName);
                                if (currentTargetSubLocation) {
                                    setTimeout(() => {
                                        selectSubLocation(currentTargetSubLocation);
                                    }, 50);
                                }
                            }
                        });
                        return;
                    }
                }
            }
        }


        function showExternalAreas(externalAreas) {
            selectedMain = null;
            selectedSub = null;
            selectedCharacterName = null;
            updateActionButtonState();

            document.getElementById('location-details').classList.add('hidden');

            document.querySelectorAll('#main-locations .location-button.selected').forEach(btn => {
                btn.classList.remove('selected');
            });
            document.getElementById('switch-area-button').classList.add('selected');

            const subLocationsContainer = document.getElementById('sub-locations');
            subLocationsContainer.innerHTML = '';

            if (!externalAreas || externalAreas.length === 0) {
                subLocationsContainer.innerHTML = '<p class="info-message">没有其他可前往的大区域。</p>';
                subLocationsContainer.classList.remove('hidden');
                return;
            }

            externalAreas.forEach(areaName => {
                if (!areaName || typeof areaName !== 'string') {
                    return;
                }
                const button = document.createElement('button');
                // Use 'sub-location-button' class for consistent styling with sub-locations when showing external areas
                button.className = 'sub-location-button external-area-button';
                // Use unified icon function for external areas
                const iconClass = getIconClassForLocation(areaName);
                button.innerHTML = `<i class="fas ${iconClass}"></i> ${areaName}`; // Display like sub-location
                button.dataset.location = areaName;
                button.addEventListener('click', () => goToExternalArea(areaName));
                subLocationsContainer.appendChild(button);
            });

            subLocationsContainer.style.gridTemplateColumns = 'repeat(auto-fill, minmax(150px, 1fr))';
            subLocationsContainer.style.gap = '12px';
            subLocationsContainer.style.padding = '15px';
            subLocationsContainer.style.backgroundColor = 'var(--theme-bg-medium)';
            subLocationsContainer.style.border = '1px solid var(--theme-border-light)';


            subLocationsContainer.classList.remove('hidden');
        }

        function goToExternalArea(areaName) {
            const cleanAreaName = areaName.replace(/[<>]/g, '');
            const message = `<request:{{user}}前往了${cleanAreaName}>`;

            if (typeof triggerSlash === 'function') {
                try {
                    triggerSlash(`/send ${message} || /trigger`);
                    resetSelection(true);
                } catch (e) {
                    alert("发送指令失败，请检查控制台信息或重试。");
                }
            } else {
                alert(`操作请求已生成 (仅供测试):\n${message}\n\n在实际环境中，这将自动发送，并刷新地图。`);
                resetSelection(true);
            }
        }

