    <style>
        @import url('https://fonts.googleapis.com/css2?family=ZCOOL+XiaoWei&family=ZCOOL+QingKe+HuangYou&display=swap');

        :root {
            /* Refined Color Palette */
            --theme-bg-dark: #2c313a; /* Slightly adjusted dark */
            --theme-bg-medium: #3e4451; /* Slightly adjusted medium */
            --theme-bg-light: #505663; /* Slightly adjusted light */
            --theme-text-light: #e6e6e6; /* Slightly brighter text */
            --theme-text-medium: #b0b0b0; /* Slightly brighter medium text */
            --theme-text-dark: #222222; /* Darker text for contrast on light bg */
            --theme-accent-orange: #e8a85e; /* Slightly brighter orange */
            --theme-accent-orange-light: #f5c58a; /* Slightly brighter light orange */
            --theme-button-color: #7cb342; /* Default button color (from settings) */
            --theme-button-hover-color: #8fd352; /* Default button hover color */
            --theme-border-light: #606673; /* Adjusted border */
            --theme-border-accent: var(--theme-accent-orange);
            --theme-success: #7cb342; /* Brighter green */
            --theme-success-hover: #8fd352;
            --theme-cancel-bg: #78909c; /* Bluish grey */
            --theme-cancel-hover: #90a4ae;

            /* Fonts */
            --font-title: "ZCOOL QingKe HuangYou", "Microsoft YaHei", sans-serif; /* 标题字体 - 可在设置中修改 */
            --font-main: "ZCOOL XiaoWei", "Microsoft YaHei", sans-serif; /* Using Google Font for main text */

            /* UI Elements */
            --border-radius-base: 8px; /* Increased slightly */
            --border-radius-small: 5px; /* Increased slightly */
            --icon-size-button: 1em;
            --shadow-subtle: 0 2px 5px rgba(0, 0, 0, 0.2);
            --shadow-medium: 0 4px 10px rgba(0, 0, 0, 0.25);

            /* Map Specific Styles */
            /* --map-rect-fill: linear-gradient(to bottom, #555a66, #4a4f5c); /* Gradient fill - Replaced by url(#mapRectFill) */
            --map-rect-stroke: #6a6f7c; /* Slightly lighter stroke */
            /* --map-rect-fill-hover: linear-gradient(to bottom, #656a76, #5a5f6c); /* Hover gradient - Replaced by url(#mapRectFillHover) */
            --map-rect-stroke-hover: var(--theme-accent-orange-light);
            /* --map-rect-fill-selected: linear-gradient(to bottom, var(--theme-accent-orange-light), var(--theme-accent-orange)); /* Selected gradient - Replaced by url(#mapRectFillSelected) */
            --map-rect-stroke-selected: var(--theme-accent-orange);
            --map-label-fill: var(--theme-text-light);
            --map-label-fill-selected: var(--theme-text-dark);
            /* --map-rect-default-fill: #4a4f5c; /* Removed: Reverting to gradient */
            /* --map-current-fill: linear-gradient(to bottom, #f5d19f, #f0c68f); /* Current gradient - Replaced by url(#mapCurrentFill) */
            --map-current-stroke: var(--theme-accent-orange);
            --map-current-label-fill: var(--theme-text-dark);
            --map-road-stroke: #777c88; /* Slightly lighter road */
            --map-bg-pattern: radial-gradient(circle at 1px 1px, rgba(255,255,255,0.03) 1px, transparent 0); /* Subtle dot pattern */
        }

        body {
            background-color: transparent; /* Keep transparent for embedding */
            margin: 0;
            padding: 10px;
            font-family: var(--font-main);
            color: var(--theme-text-light);
            box-sizing: border-box;
            font-weight: 400; /* Base weight */
        }

        .map-interface {
            max-width: 100%;
            width: 100%;
            margin: 0 auto;
            background: var(--theme-bg-dark);
            border: 2px solid var(--theme-border-light); /* Solid border */
            border-radius: var(--border-radius-base);
            box-shadow: var(--shadow-medium); /* Add shadow */
            padding: 20px;
            box-sizing: border-box;
            position: relative; /* Ensure it's positioned */
            overflow: hidden;
            min-height: 700px; /* Keep min-height */
            z-index: 100; /* Add high z-index */
        }

        .map-header {
            text-align: center;
            margin-bottom: 25px; /* Increased margin */
            padding-bottom: 15px;
            border-bottom: 1px solid var(--theme-border-light);
        }

        .map-header h2 {
            font-size: 24px; /* Slightly larger */
            margin: 0;
            padding: 0;
            line-height: 1.4;
            color: var(--theme-accent-orange-light); /* Use light orange for title */
            font-family: var(--font-title); /* Use title font variable */
            font-weight: normal; /* Use font's default weight */
            position: relative;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.3); /* Add subtle shadow */
        }
         .map-header h2:before,
         .map-header h2:after { content: none; } /* Keep this */

        .current-partners-section {
            margin-bottom: 25px; /* Increased margin */
            padding: 15px;
            background-color: rgba(232, 168, 94, 0.1); /* Use updated orange */
            border: 1px solid var(--theme-accent-orange);
            border-radius: var(--border-radius-base);
            display: block;
            box-shadow: var(--shadow-subtle); /* Add subtle shadow */
        }
        .current-partners-section.hidden {
            display: none; /* Keep hidden logic */
        }
        .current-partners-section .section-title {
            margin-bottom: 12px; /* Increased margin */
            color: var(--theme-accent-orange-light);
            font-weight: bold; /* Make title bold */
        }
        .partner-button-list {
            display: flex;
            flex-wrap: wrap;
            gap: 10px; /* Increased gap */
        }
        .partner-button {
            background-color: var(--theme-bg-light);
            border: 1px solid var(--theme-border-light);
            border-radius: var(--border-radius-small);
            padding: 7px 14px; /* Increased padding */
            font-size: 13px;
            color: var(--theme-text-light);
            cursor: pointer;
            transition: all 0.2s ease;
            display: inline-flex;
            align-items: center;
            box-shadow: var(--shadow-subtle); /* Add subtle shadow */
        }
        .partner-button i {
            margin-right: 6px; /* Increased margin */
            color: var(--theme-accent-orange);
        }
        .partner-button:hover {
            background-color: var(--theme-border-light);
            border-color: var(--theme-accent-orange-light);
            transform: translateY(-1px); /* Slight lift on hover */
            box-shadow: var(--shadow-medium); /* Enhance shadow on hover */
        }


        .movement-alert {
            background-color: rgba(224, 172, 105, 0.2);
            border: 1px solid var(--theme-accent-orange);
            border-radius: var(--border-radius-small);
            padding: 12px;
            margin-bottom: 20px;
            text-align: center;
            color: var(--theme-accent-orange-light);
        }
        .movement-alert.hidden { display: none; }
        .movement-alert i { margin-right: 8px; }

        /* --- Visual Map SVG Styles --- */
        #visual-map-container {
            position: relative;
            width: 100%;
            max-width: 800px;
            margin: 0 auto 25px auto; /* Increased margin */
            border: 2px solid var(--theme-border-light);
            background-color: var(--theme-bg-medium);
            /* Apply subtle pattern to container background */
            background-image: var(--map-bg-pattern);
            background-size: 10px 10px; /* Size of the pattern repeat */
            border-radius: var(--border-radius-base);
            overflow: hidden;
            aspect-ratio: 800 / 600;
            box-shadow: var(--shadow-medium); /* Add shadow */
            pointer-events: auto; /* Ensure container allows events through */
            position: relative; /* Add position */
            z-index: 1; /* Add z-index */
        }

        #visual-map {
            display: block;
            width: 100%;
            height: 100%;
            pointer-events: auto; /* Ensure SVG itself allows events */
        }

        .map-location-group {
            cursor: pointer;
            transition: transform 0.2s ease, filter 0.2s ease; /* Added transform */
            filter: drop-shadow(1px 1px 1px rgba(0,0,0,0.3)); /* Add subtle drop shadow */
            /* Ensure transform-origin is centered if transforms are used */
            transform-origin: center center;
            pointer-events: auto; /* Ensure group allows pointer events */
        }
        /* Remove transform on hover to prevent movement */
        .map-location-group:not(.current-location):hover {
            /* transform: scale(1.03); */ /* Removed scaling */
            filter: drop-shadow(2px 2px 3px rgba(0,0,0,0.4)); /* Keep enhanced shadow */
